export function getContractTemplate(tariffNameOrKey: string): ContractTemplate | null {
  if (!tariffNameOrKey) return null
  const clean = tariffNameOrKey.trim().toUpperCase()
  
  if (CONTRACT_TEMPLATES[clean]) {
    return CONTRACT_TEMPLATES[clean]
  }
  
  for (const [key, tpl] of Object.entries(CONTRACT_TEMPLATES)) {
    if (key.toUpperCase() === clean || tpl.title.toUpperCase().includes(clean)) {
      return tpl
    }
  }
  
  for (const [key, tpl] of Object.entries(CONTRACT_TEMPLATES)) {
    const kNorm = key.replace(/[^A-Z0-9]/g, '')
    const searchNorm = clean.replace(/[^A-Z0-9]/g, '')
    if (kNorm.includes(searchNorm) || searchNorm.includes(kNorm)) {
      return tpl
    }
  }
  
  return null
}
